const PAGE_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <link rel=\"preload\" as=\"image\" href=\"https://superintelligencesg.com/assets/commons-hero-v2.jpg\" fetchpriority=\"high\">\n  <meta name=\"theme-color\" content=\"#f4eedf\">\n  <meta name=\"description\" content=\"A public learning and discussion space for questions about Super Intelligence.\">\n  <link rel=\"canonical\" href=\"https://superintelligencesg.org/\">\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:title\" content=\"Superintelligence SG Commons | A public conversation\">\n  <meta property=\"og:description\" content=\"A public learning and discussion space for questions about Super Intelligence.\">\n  <meta property=\"og:url\" content=\"https://superintelligencesg.org/\">\n  <meta name=\"twitter:card\" content=\"summary\">\n  <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebSite\",\"name\":\"Superintelligence SG Commons\",\"url\":\"https://superintelligencesg.org/\",\"description\":\"A public, self-submitted commons for organizations shaping Super Intelligence in Singapore.\",\"publisher\":{\"@type\":\"Organization\",\"name\":\"Superintelligence SG\",\"email\":\"mailto:superintelligencesg@gmail.com\"}}</script>\n  <title>Superintelligence SG Commons | A public conversation</title>\n  <style>\n    :root{--surface:#f4eedf;--surface-raised:#fffdf6;--ink:#1d2a37;--muted:#5c686c;--line:#b9b7aa;--accent:#d84f37;--accent-ink:#fffaf1;--olive:#687749;--display:\"Avenir Next\",Avenir,\"Helvetica Neue\",sans-serif;--body:\"Avenir Next\",Avenir,\"Helvetica Neue\",sans-serif;--mono:\"SFMono-Regular\",Consolas,monospace;--radius:14px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--surface);color:var(--ink);font:400 17px/1.65 var(--body);letter-spacing:.002em}a{color:inherit;text-decoration:none}button,input,textarea{font:inherit}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid var(--accent);outline-offset:3px}::selection{background:var(--accent);color:var(--accent-ink)}::-webkit-scrollbar{width:12px}::-webkit-scrollbar-thumb{background:#9e9c8f;border:3px solid var(--surface);border-radius:20px}.shell{width:min(1320px,calc(100% - 48px));margin:auto}.skip{position:absolute;left:-999px}.skip:focus{left:20px;top:20px;z-index:10;background:var(--accent);color:var(--accent-ink);padding:10px 14px;border-radius:8px}.site-header{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:2}.brand{display:flex;align-items:center;gap:11px;font:700 13px/1 var(--display);letter-spacing:.035em;white-space:nowrap}.mark{width:25px;height:25px;border:2px solid var(--accent);border-radius:50%;position:relative}.mark:before,.mark:after{content:\"\";position:absolute;background:var(--accent)}.mark:before{height:2px;width:13px;top:10px;left:4px}.mark:after{height:13px;width:2px;top:4px;left:10px}.domain{color:var(--accent);font:11px/1 var(--mono);letter-spacing:.08em}.nav{display:flex;align-items:center;gap:26px;font-size:13px;font-weight:650}.nav a{transition:color .2s ease}.nav a:hover{color:var(--accent)}.nav .active{color:var(--accent);border-bottom:1px solid var(--accent);padding-bottom:4px}\n    .hero{min-height:calc(100dvh - 76px);position:relative;isolation:isolate;display:grid;align-items:center;overflow:hidden}.hero-media{position:absolute;inset:0;z-index:-2;margin:0}.hero-media:after{content:\"\";position:absolute;inset:0;background:linear-gradient(90deg,rgba(244,238,223,.98) 0%,rgba(244,238,223,.9) 37%,rgba(244,238,223,.32) 70%,rgba(244,238,223,.06) 100%)}.hero-media img{width:100%;height:100%;object-fit:cover;object-position:center}.hero-copy{max-width:680px;padding:72px 0}.hero h1{margin:0;max-width:11.3ch;font:600 clamp(3.8rem,7.5vw,6rem)/.97 var(--display);letter-spacing:-.04em;text-wrap:balance}.hero h1 strong{font-weight:500;color:var(--accent)}.hero p{max-width:48ch;margin:27px 0 0;color:var(--muted);font-size:19px}.button{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:12px 18px;border-radius:var(--radius);margin-top:34px;background:var(--accent);color:var(--accent-ink);font-size:14px;font-weight:700;transition:transform .2s ease,background .2s ease}.button:hover{background:#bd3e2a}.button:active{transform:translateY(1px)}\n    .section{padding:120px 0;border-top:1px solid var(--line)}.intro{max-width:760px}.intro h2,.principles h2{margin:0;font:600 clamp(2.5rem,4.1vw,3.8rem)/1.03 var(--display);letter-spacing:-.04em;text-wrap:balance}.join-intro h2{margin:0;font:600 clamp(2.6rem,5vw,4.8rem)/1.02 var(--display);letter-spacing:-.04em;text-wrap:balance}.intro p,.join-intro p{max-width:58ch;margin:20px 0 0;color:var(--muted);font-size:18px}.principles{display:grid;grid-template-columns:1fr 1.25fr;gap:12vw;align-items:start}.principle-list{border-top:1px solid var(--line)}.principle{padding:26px 0;border-bottom:1px solid var(--line)}.principle h3{margin:0;font:600 25px/1.1 var(--display);letter-spacing:-.025em}.principle p{margin:9px 0 0;color:var(--muted);font-size:16px}.guide{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:52px}.guide-item{min-height:250px;padding:25px;border:1px solid var(--line);border-radius:var(--radius);background:var(--surface-raised)}.guide-item h3{margin:0;font:600 26px/1.08 var(--display);letter-spacing:-.03em}.guide-item p{margin:16px 0 0;color:var(--muted);font-size:16px}.guide-item a{display:inline-block;margin-top:26px;color:var(--accent);font-weight:700;font-size:14px}.guide-item a:hover{text-decoration:underline;text-underline-offset:5px}.join-section{background:#e8e5d5}.join-intro{max-width:840px}.join-shell{display:grid;grid-template-columns:1fr 1fr;gap:0;margin-top:52px;border:1px solid var(--ink);border-radius:var(--radius);overflow:hidden;background:var(--surface-raised)}.join-form{padding:clamp(26px,4vw,50px);border-right:1px solid var(--line)}.join-form h3,.directory h3{margin:0;font:600 clamp(1.9rem,3vw,2.7rem)/1.1 var(--display);letter-spacing:-.035em}.form-note{margin:11px 0 28px;color:var(--muted);font-size:15px}.field{display:grid;gap:8px;margin:18px 0}.field label,.field legend{font-size:14px;font-weight:700}.field input:not([type=checkbox]),.field textarea{width:100%;min-height:49px;padding:12px 13px;border:1px solid #888f85;border-radius:10px;background:#fffef8;color:var(--ink);font-size:16px;line-height:1.45}.field textarea{min-height:128px;resize:vertical}.logo-field{display:grid;grid-template-columns:64px 1fr;align-items:center;gap:14px;padding:14px;border:1px dashed #888f85;border-radius:10px;background:#f1efe3;cursor:pointer}.logo-preview{width:64px;height:64px;display:grid;place-items:center;overflow:hidden;border:1px solid var(--line);border-radius:50%;background:#d6ddbb;color:var(--olive);font-weight:700}.logo-preview img{width:100%;height:100%;object-fit:cover}.logo-field input{position:absolute;width:1px;height:1px;opacity:0}.logo-field strong{display:block;font-size:15px}.logo-field small{display:block;margin-top:5px;color:var(--muted);font-size:13px;font-weight:400}.consent{grid-template-columns:auto 1fr;align-items:start}.consent input{width:18px;height:18px;margin-top:3px;accent-color:var(--accent)}.join-submit{width:100%;border:0;cursor:pointer}.join-submit:disabled{opacity:.58;cursor:wait}.join-status{min-height:26px;margin:14px 0 0;color:var(--muted);font-size:14px}.join-status[data-kind=\"error\"]{color:#a63629}.join-status[data-kind=\"success\"]{color:#43662f}.privacy{margin:16px 0 0;color:var(--muted);font-size:13px;line-height:1.6}.privacy a{color:var(--ink);text-decoration:underline;text-underline-offset:3px}.directory{padding:clamp(26px,4vw,50px);background:#fffef8}.directory-note{margin:11px 0 25px;color:var(--muted);font-size:15px}.directory-count{margin:0 0 14px;color:var(--olive);font:700 12px/1.4 var(--mono);letter-spacing:.04em;text-transform:uppercase}.org-list{display:grid;gap:0;max-height:610px;overflow:auto;border-top:1px solid var(--line)}.org-card{display:grid;grid-template-columns:58px minmax(0,1fr);gap:15px;padding:18px 0;border-bottom:1px solid var(--line)}.org-logo{width:58px;height:58px;object-fit:cover;border:1px solid var(--line);border-radius:50%;background:#eef0df}.org-card h4{margin:0;font:600 21px/1.2 var(--display);letter-spacing:-.02em}.org-founder{margin:5px 0 8px;color:var(--muted);font-size:13px}.org-card p{margin:0;color:var(--muted);font-size:14px;line-height:1.52;overflow-wrap:anywhere}.directory-state{margin:0;padding:22px 0;color:var(--muted);font-size:15px}.retry{border:0;background:none;padding:0;color:var(--accent);font-size:14px;font-weight:700;cursor:pointer;text-decoration:underline;text-underline-offset:4px}.directory-links{display:flex;gap:20px;flex-wrap:wrap;margin-top:25px}.directory-links a{font-size:14px;font-weight:700}.directory-links a:hover{color:var(--accent)}.cross{display:flex;justify-content:space-between;gap:28px;align-items:center;padding:34px 0;border-top:1px solid var(--line);color:var(--muted);font-size:14px}.cross-links{display:flex;gap:20px;flex-wrap:wrap}.cross a{color:var(--ink);font-weight:700}.cross a:hover{color:var(--accent)}footer{border-top:1px solid var(--line);padding:22px 0 30px;display:flex;gap:18px;justify-content:space-between;color:var(--muted);font-size:13px}footer a:hover{color:var(--accent)}\n    @media(prefers-color-scheme:dark){:root{--surface:#1c2932;--surface-raised:#25363b;--ink:#f8f1de;--muted:#bdc5be;--line:#60706c;--accent:#ff826d;--accent-ink:#212d31;--olive:#b8c995}.hero-media:after{background:linear-gradient(90deg,rgba(28,41,50,.98),rgba(28,41,50,.87) 37%,rgba(28,41,50,.3) 70%,rgba(28,41,50,.06))}.guide-item,.directory{background:var(--surface-raised)}.join-section{background:#223239}.join-shell{background:var(--surface-raised)}.logo-field{background:#2c3e3c}.field input:not([type=checkbox]),.field textarea{background:#1a282c;color:var(--ink);border-color:#71847e}.button:hover{background:#ff9c8a}}\n    @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition-duration:.01ms!important;animation-duration:.01ms!important}}\n    @media(max-width:900px){.shell{width:min(100% - 36px,1320px)}.nav{gap:16px}.nav a:not(.active){display:none}.hero{min-height:720px}.hero-media:after{background:linear-gradient(90deg,rgba(244,238,223,.97),rgba(244,238,223,.75) 65%,rgba(244,238,223,.28))}.hero-copy{padding:80px 0}.principles,.join-shell{grid-template-columns:1fr;gap:28px}.guide{grid-template-columns:1fr}.guide-item{min-height:0}.join-form{border-right:0;border-bottom:1px solid var(--line)}.section{padding:82px 0}.cross{display:block}.cross-links{margin-top:16px}footer{flex-wrap:wrap}}\n    @media(max-width:520px){.shell{width:min(100% - 30px,1320px)}.site-header{height:68px}.brand{font-size:11px}.hero{min-height:680px}.hero h1{font-size:clamp(3.25rem,15vw,4.4rem)}.hero p{font-size:17px}.button{width:100%}.intro h2,.principles h2,.join-intro h2{font-size:clamp(2.45rem,12vw,3.5rem)}.cross-links{display:grid;gap:12px}}\n  </style>\n  <style>.field .logo-field{position:relative}.field .logo-field input{position:absolute!important;width:1px!important;height:1px!important;min-height:1px!important;padding:0!important;border:0!important;opacity:0!important}.join-form>label[aria-hidden=\"true\"]{position:absolute!important;left:-10000px!important;width:1px!important;height:1px!important;overflow:hidden!important}.join-form>label[aria-hidden=\"true\"] input{width:1px!important;height:1px!important;min-height:1px!important;padding:0!important;border:0!important;opacity:0!important}</style>\n<style>.site-header.shell{width:100%;max-width:none;margin:0;padding-inline:clamp(20px,4vw,72px)}.hero-copy.shell{width:100%;max-width:none;margin:0;padding:72px clamp(20px,8vw,140px)}@media(max-width:800px){.site-header.shell{padding-inline:18px}.hero-copy.shell{padding:80px 36px}}@media(max-width:520px){.site-header.shell{padding:62px 15px}.hero-copy.shell{padding:62px 15px}}</style>\n<style>.scroll-cue{position:absolute;z-index:1;right:clamp(20px,4vw,72px);bottom:28px;display:inline-flex;align-items:center;gap:11px;color:var(--muted);font-size:12px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;transition:color .2s ease}.scroll-cue:hover{color:var(--accent)}.scroll-cue svg{width:18px;height:18px;animation:scroll-arrow 1.8s cubic-bezier(.16,1,.3,1) infinite}@keyframes scroll-arrow{0%,100%{transform:translateY(0)}55%{transform:translateY(7px)}}@media(prefers-reduced-motion:reduce){.scroll-cue svg{animation:none}}@media(max-width:520px){.scroll-cue{left:15px;right:auto;bottom:22px}}</style>\n<style>.directory-tools{display:grid;grid-template-columns:1fr auto;gap:10px;margin:0 0 18px}.directory-search{min-height:42px;width:100%;border:1px solid var(--line);border-radius:9px;background:transparent;color:var(--ink);padding:9px 11px;font-size:14px}.directory-sort{min-height:42px;border:1px solid var(--line);border-radius:9px;background:transparent;color:var(--ink);padding:8px 10px;font-size:13px}.directory-empty{padding:22px 0;margin:0;color:var(--muted);font-size:15px}@media(max-width:520px){.directory-tools{grid-template-columns:1fr}.directory-sort{width:100%}}</style>\n<style>.profile-link{display:inline-block;margin-top:10px;color:var(--accent);font-size:13px;font-weight:700}.profile-link:hover{text-decoration:underline;text-underline-offset:4px}</style>\n<style>.directory-verification{margin:8px 0 0;color:var(--olive);font:700 11px/1.4 var(--mono);letter-spacing:.04em;text-transform:uppercase}.claim-link{display:inline-block;margin-top:8px;color:var(--accent);font-size:13px;font-weight:700}.claim-link:hover{text-decoration:underline;text-underline-offset:4px}</style>\n<style>.org-card>.verification{grid-column:2;margin:8px 0 0;color:var(--olive);font:700 11px/1.4 var(--mono);letter-spacing:.04em;text-transform:uppercase}</style><style>.brand-logo{width:30px;height:30px;display:block;flex:0 0 auto}</style><link rel=\"stylesheet\" href=\"/assets/product/commons.css\"><style id=\"si-commons-mobile-typesetting\">\n.heading-break{display:block}\n@media(max-width:900px){\n  .principles h2{font-size:clamp(2.25rem,5.6vw,3rem);line-height:1.03}\n  .principles .heading-break{display:block}\n}\n@media(max-width:520px){\n  .principles h2{font-size:clamp(2.15rem,9.2vw,2.7rem)}\n}\n.open-conversation{display:block;white-space:nowrap}.conversation-word{display:block}\n@media(max-width:520px){\n  .hero h1{max-width:100%;font-size:clamp(2.4rem,9.5vw,3.4rem);line-height:.98}\n  .intro h2,.principles h2,.join-intro h2{font-size:clamp(2.25rem,10vw,3rem);line-height:1.03}\n}\n</style>\n<style id=\"si-commons-final-mobile-scale\">@media(max-width:520px){.principles h2{font-size:clamp(2.15rem,9.2vw,2.7rem)}}</style>\n<script>document.documentElement.classList.add(\"si-motion-ready\")</script><link rel=\"stylesheet\" href=\"/assets/product/si-motion.css\"><link rel=\"stylesheet\" href=\"/assets/product/si-mobile-nav.css\"></head>\n<body>\n  <a class=\"skip\" href=\"#main\">Skip to content</a>\n  <header class=\"shell site-header\"><a class=\"brand\" href=\"https://superintelligencesg.org\" aria-label=\"Superintelligence SG Commons home\"><img class=\"brand-logo\" src=\"assets/logo-org.svg\" alt=\"Superintelligence SG Commons logo\">SUPERINTELLIGENCE SG <span class=\"domain\">.ORG</span></a><nav class=\"nav\" aria-label=\"Site navigation\"><a class=\"active\" href=\"https://superintelligencesg.org\">Home</a><a href=\"https://superintelligencesg.com\">Overview</a><a href=\"https://superintelligencesg.ai\">Lab</a><a href=\"about.html\">About</a></nav></header>\n  <main id=\"main\">\n    <section class=\"hero\"><figure class=\"hero-media\"><img src=\"https://superintelligencesg.com/assets/commons-hero-v2.jpg\" width=\"1586\" height=\"992\" alt=\"People collaborating around a shared map in a sunlit community room\"></figure><div class=\"shell hero-copy\"><h1>The future needs an <strong><span class=\"open-conversation\">open <span class=\"conversation-word\">conversation.</span></span></strong></h1><p>A public space for shared language, careful questions and more voices in the future of Super Intelligence (SI).</p><a class=\"button\" href=\"#participate\">Join the commons</a></div><a class=\"scroll-cue\" href=\"#learn\"><span>Meet the commons</span><svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"M12 3v17m0 0 6-6m-6 6-6-6\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></a></section>\n    <section class=\"section\"><div class=\"shell principles\"><h2>Make room for <span class=\"heading-break\">what changes when</span> <span class=\"heading-break\">more people take part.</span></h2><div class=\"principle-list\"><article class=\"principle\"><h3>Ask who shapes the goal.</h3><p>Look at whose priorities are built into a system and whose needs may sit outside its design.</p></article><article class=\"principle\"><h3>Follow what changes at scale.</h3><p>A small decision can travel through a workplace, service or community in ways that matter.</p></article><article class=\"principle\"><h3>Keep judgment available.</h3><p>People need ways to understand, challenge and revise consequential choices.</p></article></div></div></section>\n    <section class=\"section\" id=\"learn\"><div class=\"shell intro\"><h2>A practical guide for better questions.</h2><p>These prompts are a place to start. Take one into a conversation and add the context of your own work and life.</p></div><div class=\"shell guide\"><article class=\"guide-item\"><h3>What do we mean by Super Intelligence?</h3><p>Separate a system's demonstrated capability from the hopes or fears attached to it.</p><a href=\"https://superintelligencesg.ai\">Explore a system lens</a></article><article class=\"guide-item\"><h3>How do we talk about uncertainty?</h3><p>Name the time horizon, assumptions and people most affected. Let confidence match the evidence.</p><a href=\"https://superintelligencesg.com/#october-signal\">See the latest public signal</a></article><article class=\"guide-item\"><h3>What does participation look like?</h3><p>Make the question specific, share the constraints and explain what can still change.</p><a href=\"#participate\">Publish your organization</a></article></div></section>\n    <section class=\"section join-section\" id=\"participate\"><div class=\"shell\"><div class=\"join-intro\"><h2>Make your work easier to find.</h2><p>Joining is voluntary and immediate. Share your work, explain the collaboration you welcome, and maintain your own public profile. Publishing is immediate; website verification is a separate step.</p></div><div class=\"product-actions\"><a class=\"product-button\" href=\"/organizations.html\">Browse organisation profiles</a><a class=\"product-button\" href=\"/manage.html\">Manage or claim your profile</a></div><div class=\"join-shell\"><form class=\"join-form\" data-org-form><h3>Publish your profile.</h3><p class=\"form-note\">Self-submitted entries are public. No approval is required.</p><div class=\"field\"><label class=\"logo-field\" for=\"org-logo\"><span class=\"logo-preview\" data-logo-preview aria-hidden=\"true\">SG</span><span><strong>Upload your organization logo</strong><small>PNG, JPG or WebP, up to 2 MB. It is optimized before upload.</small></span><input id=\"org-logo\" name=\"logo\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" required aria-label=\"Upload organization logo\"></label></div><div class=\"field\"><label for=\"org-name\">Organization name</label><input id=\"org-name\" name=\"name\" required maxlength=\"100\" autocomplete=\"organization\" placeholder=\"Name shown in the directory\"></div><div class=\"field\"><label for=\"org-founder\">Founder</label><input id=\"org-founder\" name=\"founder\" required maxlength=\"100\" placeholder=\"Founder or founding team\"></div><div class=\"field\"><label for=\"org-business\">Core work</label><textarea id=\"org-business\" name=\"business\" required maxlength=\"500\" placeholder=\"In a few sentences, what does your organization focus on?\"></textarea></div><div class=\"field consent\"><input id=\"org-consent\" name=\"consent\" type=\"checkbox\" required><label for=\"org-consent\">I represent this organization and agree that these details and logo can be displayed publicly.</label></div><label aria-hidden=\"true\" style=\"position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden\">Leave this field empty<input name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label><button class=\"button join-submit\" type=\"submit\">Join and publish</button><p class=\"join-status\" data-join-status aria-live=\"polite\"></p><p class=\"privacy\">Your profile details and contact link are public. After publishing, save your private management key to edit or withdraw your profile. For help, email <a href=\"mailto:superintelligencesg@gmail.com\">superintelligencesg@gmail.com</a>.</p></form><aside class=\"directory\" aria-labelledby=\"directory-title\"><h3 id=\"directory-title\">Organizations in the conversation</h3><p class=\"directory-note\">A self-submitted public directory for Singapore's Super Intelligence (SI) ecosystem.</p><p class=\"directory-count\" data-directory-count>Loading the directory</p><div class=\"org-list\" data-org-list aria-live=\"polite\"><p class=\"directory-state\">Loading public entries.</p></div><div class=\"directory-links\"><a href=\"https://superintelligencesg.com\">About the initiative</a><a href=\"https://superintelligencesg.ai\">Explore the lab</a></div></aside></div></div></section>\n  </main>\n  <section class=\"shell cross\" aria-label=\"Explore Superintelligence SG\"><span>One initiative, three doors.</span><div class=\"cross-links\"><a href=\"https://superintelligencesg.org\">Home</a><a href=\"https://superintelligencesg.com\">Overview</a><a href=\"https://superintelligencesg.ai\">Lab</a></div></section>\n  <footer class=\"shell\"><span>Superintelligence SG</span><a href=\"mailto:superintelligencesg@gmail.com\">superintelligencesg@gmail.com</a><a href=\"#main\">Back to top</a></footer>\n\n\n\n<script src=\"/assets/product/commons.js\" defer></script><script src=\"/assets/product/si-motion.js\" defer></script></body>\n</html>\n";
